// buildReq wraps a fixture query into a BuildRequestRequest (no auth context —
// the anonymous tier carries no credentials).
func buildReq(t *testing.T, query map[string]any) *metadatav1.BuildRequestRequest {
	t.Helper()
	q, err := structpb.NewStruct(query)
	if err != nil {
		t.Fatalf("fixture query struct: %v", err)
	}
	return &metadatav1.BuildRequestRequest{Query: q}
}

// buildSpec is the box-1.2 assertion block every spec must satisfy: an
// app-named User-Agent (never a default/library UA — shikimori.io bans them),
// the 700 ms pacing (the 90 rpm anonymous cap), no secret variables, and GET
// with an empty body.
func buildSpec(t *testing.T, spec *metadatav1.RequestSpec) {
	t.Helper()
	ua, ok := spec.GetHeaders()["User-Agent"]
	if !ok || ua != userAgent || userAgent == "" {
		t.Fatalf("User-Agent = %q (present=%v), want the app-named %q", ua, ok, userAgent)
	}
	if spec.GetHeaders()["Authorization"] != "" {
		t.Error("Authorization header present, want none at the anonymous tier")
	}
	if got := spec.GetMinIntervalMs(); got != minIntervalMS {
		t.Errorf("min_interval_ms = %d, want %d (the 90 rpm anonymous cap)", got, minIntervalMS)
	}
	if len(spec.GetBody()) != 0 {
		t.Errorf("body = %q, want empty for a GET spec", spec.GetBody())
	}
	for name, v := range spec.GetVariables() {
		if ref := v.GetRedactedRef(); ref != "" {
			t.Errorf("variable %q carries redacted_ref %q, want no secret variables", name, ref)
		}
	}
}

// TestBuildRequest drives the endpoint shapes (box 1.2): the anchored by-id
// template, the bounded anime search, and the movie-kind filter, each against
// the anonymous-tier contract.
func TestBuildRequest(t *testing.T) {
	p := &sourceImpl{}

	t.Run("anchored query resolves the by-id template", func(t *testing.T) {
		res, err := p.BuildRequest(context.Background(),
			buildReq(t, map[string]any{"shikimori_id": int64(123)}))
		if err != nil {
			t.Fatalf("BuildRequest: %v", err)
		}
		spec := res.GetSpec()
		if got := spec.GetMethod(); got != "GET" {
			t.Errorf("method = %q, want GET", got)
		}
		if got := spec.GetUrlTemplate(); got != anchoredTemplate {
			t.Errorf("url_template = %q, want %q", got, anchoredTemplate)
		}
		// The placeholder and the variable key must agree by NAME: the core
		// rejects a template placeholder with no declared variable (terminal
		// spec error), so a one-sided rename can never reappear.
		if !strings.Contains(spec.GetUrlTemplate(), "{shikimori_id}") {
			t.Errorf("url_template = %q, want the {shikimori_id} placeholder (agreement with the variables key)", spec.GetUrlTemplate())
		}
		if got := spec.GetVariables()["shikimori_id"].GetIntValue(); got != 123 {
			t.Errorf("variables[shikimori_id] = %d, want 123", got)
		}
		buildSpec(t, spec)
	})

	t.Run("anime search carries title and bounded page size", func(t *testing.T) {
		res, err := p.BuildRequest(context.Background(),
			buildReq(t, map[string]any{"title": "Во все тяжкие", "season": int64(1)}))
		if err != nil {
			t.Fatalf("BuildRequest: %v", err)
		}
		spec := res.GetSpec()
		want := "https://shikimori.io/api/animes?search={title}&limit=10"
		if got := spec.GetUrlTemplate(); got != want {
			t.Errorf("url_template = %q, want %q", got, want)
		}
		if got := spec.GetVariables()["title"].GetStringValue(); got != "Во все тяжкие" {
			t.Errorf("variables[title] = %q, want the display title", got)
		}
		if _, ok := spec.GetVariables()["season"]; ok {
			t.Error("season leaked into spec variables, want the search shaped by title only")
		}
		buildSpec(t, spec)
	})

	t.Run("movie-kind query adds the kind filter", func(t *testing.T) {
		res, err := p.BuildRequest(context.Background(),
			buildReq(t, map[string]any{"title": "Perfect Blue", "kind": "movie"}))
		if err != nil {
			t.Fatalf("BuildRequest: %v", err)
		}
		spec := res.GetSpec()
		if got := spec.GetUrlTemplate(); !strings.HasSuffix(got, "&kind={kind}") {
			t.Errorf("url_template = %q, want the kind filter appended", got)
		}
		if got := spec.GetVariables()["kind"].GetStringValue(); got != "movie" {
			t.Errorf("variables[kind] = %q, want movie", got)
		}
		buildSpec(t, spec)
	})
}
